import{at as e,it as t,n,vt as r}from"./chunks/framework.CW63qgVu.js";var i=JSON.parse(`{"title":"Accounts","description":"User accounts in retroBITE: the first-run setup, signing in, adding users and resetting passwords from the command line, and what every account can do.","frontmatter":{"title":"Accounts","description":"User accounts in retroBITE: the first-run setup, signing in, adding users and resetting passwords from the command line, and what every account can do.","order":9},"headers":[],"relativePath":"docs/guide/accounts.md","filePath":"docs/guide/accounts.md","lastUpdated":1791277802000}`),a={name:`docs/guide/accounts.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to “Accounts”">​</a></h1><p>retroBITE has its own user accounts for the web interface. You create the first one during setup and add more from the command line. There is no sign-up page and no password reset by email, because retroBITE assumes no mail server.</p><p>The SMB and FTP account consoles use is separate. It is set by <code>AUTH_USER</code> and <code>AUTH_PASS</code> in <code>.env</code>, as described in <a href="./../getting-started/configuration#network-shares">Configuration</a>.</p><h2 id="first-run-setup" tabindex="-1">First-run setup <a class="header-anchor" href="#first-run-setup" aria-label="Permalink to “First-run setup”">​</a></h2><p>The first time you open retroBITE, a four-step setup walks you through the basics:</p><ol><li><strong>Account</strong>: choose the username and password for the first account.</li><li><strong>Interface</strong>: color scheme, scanlines and how game pages look.</li><li><strong>ScreenScraper</strong>: your ScreenScraper account, for metadata and artwork.</li><li><strong>RetroAchievements</strong>: your RetroAchievements account, to sync achievements.</li></ol><p>Every page leads to the setup until it is finished. If you close the tab part way, you continue where you left off after signing in. Once setup is finished, it cannot be opened again. Every setting it covers stays available under <strong>Settings</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Finish setup before sharing the address</p><p>Until the first account exists, the account step is open to anyone who can reach retroBITE, and whoever gets there first creates the account. Complete the setup before you make retroBITE reachable from other devices or networks.</p></div><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to “Signing in”">​</a></h2><p>Sign in with your username or your email address. Accounts created during setup or from the command line are ready to use straight away.</p><p>Change your name, email address and password under <strong>Settings → User</strong>. Changing the password needs the current one.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to “Permissions”">​</a></h2><p>Every account has the same permissions. There are no roles and no read-only accounts: any signed-in user can change settings for the whole install, edit the library, run conversions and transfers, and add or edit hardware docs.</p><div class="danger custom-block"><p class="custom-block-title">Be careful who you give an account to</p><p>An account gives full control over retroBITE and your library. Only create accounts for people you trust with that.</p></div><h2 id="managing-accounts-from-the-command-line" tabindex="-1">Managing accounts from the command line <a class="header-anchor" href="#managing-accounts-from-the-command-line" aria-label="Permalink to “Managing accounts from the command line”">​</a></h2><p>Accounts are created and reset with retroBITE&#39;s <code>user</code> commands, run inside the web container from the machine that runs retroBITE. Run them from the folder with your <code>docker-compose.yml</code>.</p><p>If you run retroBITE from a checkout of the source repository, the <code>./retrobite</code> script runs the same commands for you.</p><h3 id="create-an-account" tabindex="-1">Create an account <a class="header-anchor" href="#create-an-account" aria-label="Permalink to “Create an account”">​</a></h3><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-77" id="tab-78" checked><label data-title="Docker Compose" for="tab-78">Docker Compose</label><input type="radio" name="group-77" id="tab-79"><label data-title="./retrobite" for="tab-79">./retrobite</label></div><div class="blocks"><div class="language-bash active"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www-data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> retrobite-web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> retrogamer</span></span></code></pre></div><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./retrobite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> retrogamer</span></span></code></pre></div></div></div><p>You are asked for the password, which is not shown as you type. Leave out the username to be asked for that too.</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>What it sets</th></tr></thead><tbody><tr><td><code>--email=</code></td><td><code>&lt;username&gt;@retrobite.local</code></td><td>The email address, which also works for signing in</td></tr><tr><td><code>--name=</code></td><td>the username</td><td>The display name</td></tr><tr><td><code>--password=</code></td><td>asked for</td><td>The password. Prefer the prompt: a password on the command line ends up in your shell history.</td></tr></tbody></table><p>For example:</p><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-137" id="tab-138" checked><label data-title="Docker Compose" for="tab-138">Docker Compose</label><input type="radio" name="group-137" id="tab-139"><label data-title="./retrobite" for="tab-139">./retrobite</label></div><div class="blocks"><div class="language-bash active"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www-data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> retrobite-web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> retrogamer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --email=me@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Player One&quot;</span></span></code></pre></div><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./retrobite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> retrogamer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --email=me@example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Player One&quot;</span></span></code></pre></div></div></div><h3 id="reset-a-password" tabindex="-1">Reset a password <a class="header-anchor" href="#reset-a-password" aria-label="Permalink to “Reset a password”">​</a></h3><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-144" id="tab-145" checked><label data-title="Docker Compose" for="tab-145">Docker Compose</label><input type="radio" name="group-144" id="tab-146"><label data-title="./retrobite" for="tab-146">./retrobite</label></div><div class="blocks"><div class="language-bash active"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> www-data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> retrobite-web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> retrogamer</span></span></code></pre></div><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./retrobite</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user:password</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> retrogamer</span></span></code></pre></div></div></div><p>The argument takes a username or an email address. If nothing matches exactly, it falls back to a partial match and lets you pick when several accounts match. Leave it out to be asked. The new password is asked for without echoing, or can be passed with <code>--password=</code>.</p>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};